const BIRDS = [
{"no": "001", "en": "Northern Emerald-Toucanet", "short": "Emerald-Toucanet", "la": "Aulacorhynchus prasinus", "cat": "Tucanet maragda", "local": "Tucancillo verde", "localLang": "CR", "mapSrc": "EBIRD", "types": ["FRUGIVORE", "CLOUD FOREST"], "size": [29, 37], "weight": [171, 171], "alt": [800, 3000], "status": "LC", "fact": "It swallows fruit whole, then brings it back up to eat the pulp and spit out the seeds. Often called a gardener of the cloud forest.", "photoPlace": "SAN GERARDO DE DOTA, CR", "seen": [["2026-07-30", "Feathers Garden, San Gerardo de Dota, Costa Rica"]], "links": [], "photo": "img/photos/001.jpg", "map": "img/maps/001.png", "sprite": "img/sprites/001.png", "regions": ["CENTRAL AMERICA"], "fact_ca": "S'empassa la fruita sencera i després la regurgita per menjar-se la polpa i escopir les llavors. Sovint se'l considera un jardiner del bosc nuvolós.", "family": "Ramphastidae"},
{"no": "002", "en": "Keel-billed Toucan", "short": "Keel-billed Toucan", "la": "Ramphastos sulfuratus", "cat": "Tucà becverdós", "local": "Tucán pico iris", "localLang": "CR", "mapSrc": "BIRDS OF THE WORLD", "types": ["FRUGIVORE", "RAINFOREST"], "size": [42, 55], "weight": [410, 410], "alt": [0, 1900], "status": "NT", "fact": "Its rainbow bill is a third of its body length, yet it's light: hollow bone covered in keratin. It's also the national bird of Belize.", "photoPlace": "COSTA RICA", "seen": [["2026-07-08", "Tortuguero, Costa Rica"], ["2026-07-09", "Caño Aguas Frías, Tortuguero, Costa Rica"], ["2026-07-10", "Tortuguero, Costa Rica"], ["2026-07-14", "Sonora Jungle Retreat, Costa Rica"]], "links": [], "photo": "img/photos/002.jpg", "map": "img/maps/002.png", "sprite": "img/sprites/002.png", "regions": ["CENTRAL AMERICA", "SOUTH AMERICA"], "fact_ca": "El bec, amb tots els colors de l'arc de Sant Martí, fa un terç del cos, però és lleuger: és os buit recobert de queratina. També és l'ocell nacional de Belize.", "family": "Ramphastidae"},
{"no": "003", "en": "Yellow-throated Toucan", "short": "Yellow-throated Toucan", "la": "Ramphastos ambiguus", "cat": "Tucà pitgroc", "local": "Tucán pico castaño", "localLang": "CR", "sprite": "img/sprites/003.png", "seen": [["2026-07-09", "Caño Aguas Frías, Tortuguero, Costa Rica"], ["2026-07-10", "Tortuguero, Costa Rica"], ["2026-07-17", "Estación Biológica La Selva, Costa Rica"], ["2026-07-28", "Matapalo, Osa, Costa Rica"]], "regions": ["CENTRAL AMERICA", "SOUTH AMERICA"], "types": ["FRUGIVORE", "RAINFOREST"], "size": [47, 61], "weight": [652, 652], "alt": [0, 2500], "status": "LC", "fact": "Its yelping call sounds like 'Dios te dé, te dé!' (Spanish for 'May God give you'). It's the largest toucan in Central America.", "links": [], "photo": "img/photos/003.jpg", "photoPlace": "TORTUGUERO, CR", "map": "img/maps/003.png", "mapSrc": "EBIRD", "fact_ca": "El seu crit sona com «Dios te dé, te dé!» («Que Déu et doni», en castellà). És el tucà més gran de l'Amèrica Central.", "family": "Ramphastidae"},
{"no": "004", "en": "Fiery-billed Aracari", "short": "Fiery-billed Aracari", "la": "Pteroglossus frantzii", "cat": "Araçarí de Frantzius", "local": "Tucancillo piquianaranjado", "localLang": "CR", "sprite": "img/sprites/004.png", "seen": [["2026-07-26", "Piro, Puerto Jiménez, Costa Rica"], ["2026-07-28", "Matapalo, Osa, Costa Rica"]], "regions": ["CENTRAL AMERICA"], "types": ["FRUGIVORE", "RAINFOREST"], "size": [45, 45], "weight": [253, 253], "alt": [0, 1200], "status": "LC", "fact": "It lives only in southern Costa Rica and western Panama. Young birds from last year often stay to help feed their new siblings.", "links": [], "photo": "img/photos/004.jpg", "photoPlace": "OSA, CR", "map": "img/maps/004.png", "mapSrc": "WIKIMEDIA", "fact_ca": "Només viu al sud de Costa Rica i a l'oest de Panamà. Els joves de l'any anterior sovint es queden a ajudar a alimentar els nous germans.", "family": "Ramphastidae"},
{"no": "005", "en": "Collared Aracari", "short": "Collared Aracari", "la": "Pteroglossus torquatus", "cat": "Araçarí de collar", "local": "Tucancillo collarejo", "localLang": "CR", "sprite": "img/sprites/005.png", "seen": [["2026-07-12", "Sonora Jungle Retreat, Costa Rica"], ["2026-07-13", "Sonora Jungle Retreat, Costa Rica"], ["2026-07-14", "Sonora Jungle Retreat, Costa Rica"], ["2026-07-17", "Estación Biológica La Selva, Costa Rica"]], "regions": ["CENTRAL AMERICA", "SOUTH AMERICA"], "types": ["FRUGIVORE", "RAINFOREST"], "size": [38, 41], "weight": [219, 219], "alt": [0, 1500], "status": "LC", "fact": "Up to seven squeeze into one tree hole to sleep. Its wings make an audible whir when it flies.", "links": [], "photo": "img/photos/005.jpg", "photoPlace": "COSTA RICA", "map": "img/maps/005.png", "mapSrc": "WIKIMEDIA", "fact_ca": "Fins a set ocells s'encabeixen en un sol forat d'arbre per dormir. Quan volen, les ales fan un brunzit que se sent bé.", "family": "Ramphastidae"},
{"no": "006", "en": "Resplendent Quetzal", "short": "Resplendent Quetzal", "la": "Pharomachrus mocinno", "cat": "Quetzal esplèndid", "local": "Quetzal", "localLang": "CR", "sprite": "img/sprites/006.png", "seen": [["2026-07-21", "Monteverde Cloud Forest Reserve, Costa Rica"], ["2026-07-30", "Feathers Garden, San Gerardo de Dota, Costa Rica"]], "regions": ["CENTRAL AMERICA"], "types": ["FRUGIVORE", "CLOUD FOREST"], "size": [36, 40], "weight": [202, 202], "alt": [900, 3200], "status": "NT", "fact": "That long 'tail' isn't a tail: those are upper tail coverts, which can grow up to 1 m in males. The real tail is short and white underneath.", "links": [], "photo": "img/photos/006.jpg", "photoPlace": "COSTA RICA", "map": "img/maps/006.png", "mapSrc": "BIRDS OF THE WORLD", "fact_ca": "Aquesta llarga «cua» no és la cua: són les plomes cobertores de sobre la cua, que en els mascles poden fer fins a 1 m. La cua de debò és curta i blanca per sota.", "family": "Trogonidae"},
{"no": "007", "en": "Fiery-throated Hummingbird", "short": "Fiery-throated Hummingbird", "la": "Panterpe insignis", "cat": "Colibrí insigne", "local": "Colibrí garganta de fuego", "localLang": "CR", "sprite": "img/sprites/007.png", "seen": [["2026-08-01", "Paraíso Quetzal Lodge, Cerro de la Muerte, Costa Rica"]], "regions": ["CENTRAL AMERICA"], "types": ["NECTARIVORE", "CLOUD FOREST"], "size": [10.5, 11], "weight": [5.7, 5.7], "alt": [1600, 3200], "status": "LC", "fact": "Small but bossy: it chases off most other hummingbirds, and steals nectar through holes in flowers too deep for its bill.", "links": [], "photo": "img/photos/007.jpg", "photoPlace": "CERRO DE LA MUERTE, CR", "map": "img/maps/007.png", "mapSrc": "EBIRD", "fact_ca": "Petit però manaire: fa fora la majoria dels altres colibrís, i roba el nèctar de les flors massa fondes per al seu bec a través de forats a la base.", "family": "Trochilidae"},
{"no": "008", "en": "Talamanca Hummingbird", "short": "Talamanca Hummingbird", "la": "Eugenes spectabilis", "cat": "Colibrí de Talamanca", "local": "Colibrí de Talamanca", "localLang": "CR", "sprite": "img/sprites/008.png", "seen": [["2026-07-30", "Feathers Garden, San Gerardo de Dota, Costa Rica"], ["2026-07-30", "Savegre Hotel, San Gerardo de Dota, Costa Rica"], ["2026-08-01", "Paraíso Quetzal Lodge, Cerro de la Muerte, Costa Rica"]], "regions": ["CENTRAL AMERICA"], "types": ["NECTARIVORE", "CLOUD FOREST"], "size": [13, 13], "weight": [8.5, 10], "alt": [2000, 3300], "status": "LC", "fact": "Until 2017 it was considered part of the Magnificent Hummingbird. It hangs its mossy nest from bamboo stems.", "links": [], "photo": "img/photos/008.jpg", "photoPlace": "SAN GERARDO DE DOTA, CR", "map": "img/maps/008.png", "mapSrc": "WIKIMEDIA", "fact_ca": "Fins al 2017 es considerava part del colibrí magnífic. Penja el niu, fet de molsa, de tiges de bambú.", "family": "Trochilidae"},
{"no": "009", "en": "Volcano Hummingbird", "short": "Volcano Hummingbird", "la": "Selasphorus flammula", "cat": "Colibrí dels volcans", "local": "Chispita volcanera", "localLang": "CR", "sprite": "img/sprites/009.png", "seen": [["2026-07-29", "Savegre Hotel, San Gerardo de Dota, Costa Rica"], ["2026-07-30", "Feathers Garden, San Gerardo de Dota, Costa Rica"], ["2026-08-01", "Paraíso Quetzal Lodge, Cerro de la Muerte, Costa Rica"]], "regions": ["CENTRAL AMERICA"], "types": ["NECTARIVORE", "PARAMO"], "size": [7.5, 8], "weight": [2.7, 2.7], "alt": [1800, 3500], "status": "LC", "fact": "The male's throat changes color depending on the mountains where it lives: rosy red on Irazú and Turrialba, purple on Poás and Barva, and dull grey-lilac in Talamanca.", "links": [], "photo": "img/photos/009.jpg", "photoPlace": "SAN GERARDO DE DOTA, CR", "map": "img/maps/009.png", "mapSrc": "EBIRD", "fact_ca": "El color de la gola del mascle canvia segons les muntanyes on viu: rosa vermellós a l'Irazú i el Turrialba, porpra al Poás i el Barva, i gris liladenc apagat a Talamanca.", "family": "Trochilidae"},
{"no": "010", "en": "Great Green Macaw", "short": "Great Green Macaw", "la": "Ara ambiguus", "cat": "Guacamai verd gros", "local": "Lapa verde", "localLang": "CR", "sprite": "img/sprites/010.png", "seen": [["2026-07-08", "Tortuguero, Costa Rica"], ["2026-07-09", "Caño Aguas Frías, Tortuguero, Costa Rica"]], "regions": ["CENTRAL AMERICA", "SOUTH AMERICA"], "types": ["GRANIVORE", "RAINFOREST"], "size": [85, 90], "weight": [1300, 1300], "alt": [0, 1000], "status": "CR", "fact": "Critically endangered: only 500 to 1,000 adults remain in the wild. It depends on a single tree, the almendro, for both nesting and food.", "links": [], "photo": "img/photos/010.jpg", "photoPlace": "TORTUGUERO, CR", "map": "img/maps/010.png", "mapSrc": "EBIRD", "fact_ca": "En perill crític: només en queden entre 500 i 1.000 adults en llibertat. Depèn d'un sol arbre, l'almendro (Dipteryx oleifera), per fer el niu i per menjar.", "short_ca": "Guacamai verd", "family": "Psittacidae"},
{"no": "011", "en": "Scarlet Macaw", "short": "Scarlet Macaw", "la": "Ara macao", "cat": "Guacamai roig alagroc", "local": "Lapa roja", "localLang": "CR", "sprite": "img/sprites/011.png", "seen": [["2026-07-15", "Tirimbina Rainforest Center, Costa Rica"], ["2026-07-23", "Playa Agujas, Costa Rica"], ["2026-07-24", "Marino Ballena NP, Uvita, Costa Rica"], ["2026-07-26", "Playa Pan Dulce, Golfito, Costa Rica"], ["2026-07-28", "Matapalo, Osa, Costa Rica"]], "regions": ["CENTRAL AMERICA", "SOUTH AMERICA"], "types": ["GRANIVORE", "RAINFOREST"], "size": [84, 84], "weight": [1015, 1015], "alt": [0, 1000], "status": "LC", "fact": "It can live 40 to 50 years. Flocks gather at riverbank clay licks to eat mineral-rich soil. It's the national bird of Honduras.", "links": [], "photo": "img/photos/011.jpg", "photoPlace": "COSTA RICA", "map": "img/maps/011.png", "mapSrc": "WIKIMEDIA", "fact_ca": "Pot viure entre 40 i 50 anys. Els estols es reuneixen als marges argilosos dels rius per menjar terra rica en minerals. És l'ocell nacional d'Hondures.", "short_ca": "Guacamai roig", "family": "Psittacidae"},
{"no": "012", "en": "Common Kingfisher", "short": "Common Kingfisher", "la": "Alcedo atthis", "cat": "Blauet", "local": "Martín pescador", "localLang": "ES", "sprite": "img/sprites/012.png", "seen": [["2024-08-18", "Aguait Quim Franch, Aiguamolls de l'Empordà, Catalonia"], ["2024-09-10", "Cortalet - Mas Matà, Aiguamolls de l'Empordà, Catalonia"], ["2024-12-09", "Castelló d'Empúries, Catalonia"], ["2026-02-22", "Estany del Cortalet, Aiguamolls de l'Empordà, Catalonia"]], "regions": ["EUROPE", "ASIA", "AFRICA"], "types": ["AQUATIC PREDATOR", "WETLAND"], "size": [16, 16], "weight": [31, 31], "alt": [0, 1500], "status": "LC", "fact": "You'll usually see it as a flash of electric blue shooting low over the water in the wetlands, rivers and ponds where it lives.", "links": [], "map": "img/maps/012.png", "mapSrc": "EBIRD", "spriteF": "img/sprites/012_f.png", "seasonal": true, "fact_ca": "Normalment el veuràs com un llamp de color blau que passa arran d'aigua als aiguamolls, rius i basses on viu.", "family": "Alcedinidae", "fact2": "In the 1990s, Japan's Shinkansen bullet trains made a loud boom when leaving tunnels at high speed. Engineer Eiji Nakatsu, a birdwatcher, copied the kingfisher's bill, which dives into water with barely a splash. The new long nose cut the noise and made the train about 10% faster using about 15% less energy.", "fact2_ca": "Als anys 90, els trens bala japonesos Shinkansen feien un esclat sorollós en sortir dels túnels a gran velocitat. L'enginyer Eiji Nakatsu, que era ocellaire, va copiar el bec del blauet, que entra a l'aigua gairebé sense esquitxar. El nou morro llarg va reduir el soroll i va fer el tren un 10% més ràpid gastant un 15% menys d'energia.", "photo": "img/photos/012.jpg", "photoPlace": "CATALONIA"},
{"no": "013", "en": "Grey Heron", "short": "Grey Heron", "la": "Ardea cinerea", "cat": "Bernat pescaire", "local": "Garza real", "localLang": "ES", "regions": ["EUROPE", "AFRICA", "ASIA"], "types": ["AQUATIC PREDATOR", "WETLAND"], "sprite": "img/sprites/013.png", "seen": [["2024-08-10", "Aguait de les Comes, Aiguamolls de l'Empordà, Catalonia"], ["2024-08-22", "Aguait del Bruel, Aiguamolls de l'Empordà, Catalonia"], ["2025-01-16", "Closa del Puig, Aiguamolls de l'Empordà, Catalonia"], ["2026-02-22", "Estany del Cortalet, Aiguamolls de l'Empordà, Catalonia"], ["2026-07-04", "Casa Verda, Delta de l'Ebre, Catalonia"]], "size": [84, 102], "weight": [1443, 1443], "alt": [0, 1500], "status": "LC", "fact": "It has special 'powder down' feathers that crumble into a talc-like dust, which it uses to clean fish slime off its plumage.", "fact2": "In medieval Europe, roast heron was a prized dish at royal banquets: 400 were served at a single feast in York in 1465.", "links": [], "photo": "img/photos/013.jpg", "photoPlace": "CATALONIA", "map": "img/maps/013.png", "mapSrc": "BIRDS OF THE WORLD", "seasonal": true, "fact_ca": "Té unes plomes especials que es desfan en una pols semblant al talc, i la fa servir per treure's del plomatge la mucositat dels peixos.", "fact2_ca": "A l'Europa medieval, el bernat rostit era un plat apreciat als banquets reials: en un sol festí a York, el 1465, se'n van servir 400.", "family": "Ardeidae"},
{"no": "014", "en": "Purple Heron", "short": "Purple Heron", "la": "Ardea purpurea", "cat": "Agró roig", "local": "Garza imperial", "localLang": "ES", "regions": ["EUROPE", "AFRICA", "ASIA"], "types": ["AQUATIC PREDATOR", "WETLAND"], "sprite": "img/sprites/014.png", "seen": [["2024-08-14", "Aguait Quim Franch, Aiguamolls de l'Empordà, Catalonia"], ["2026-07-04", "Casa Verda, Delta de l'Ebre, Catalonia"]], "size": [78, 97], "weight": [1064, 1064], "alt": [0, 1000], "status": "LC", "fact": "Satellite-tracked purple herons flew from the Netherlands to the Sahel, about 4,000 km, in just 5 to 7 days. One flew 5,600 km non-stop, mostly over the sea.", "links": [], "map": "img/maps/014.png", "mapSrc": "WIKIMEDIA", "seasonal": true, "fact_ca": "Uns agrons roigs seguits per satèl·lit van volar dels Països Baixos al Sahel, uns 4.000 km, en només 5 a 7 dies. Un va fer 5.600 km sense parar, gairebé tot per sobre del mar.", "family": "Ardeidae", "photo": "img/photos/014.jpg", "photoPlace": "CATALONIA"},
{"no": "015", "en": "Great Egret", "short": "Great Egret", "la": "Ardea alba", "cat": "Agró blanc", "local": "Garceta grande", "localLang": "ES", "regions": ["EUROPE", "AFRICA", "ASIA", "NORTH AMERICA", "CENTRAL AMERICA", "SOUTH AMERICA", "OCEANIA"], "types": ["AQUATIC PREDATOR", "WETLAND"], "sprite": "img/sprites/015.png", "seen": [["2024-08-18", "Aguait de les Dantes, Aiguamolls de l'Empordà, Catalonia"], ["2024-12-17", "Castelló d'Empúries, Catalonia"], ["2024-12-24", "Aguait de les Comes, Aiguamolls de l'Empordà, Catalonia"], ["2025-04-17", "Estany del Cortalet, Aiguamolls de l'Empordà, Catalonia"], ["2026-02-22", "Estany del Cortalet, Aiguamolls de l'Empordà, Catalonia"], ["2026-07-28", "Matapalo, Osa, Costa Rica"]], "size": [80, 104], "weight": [871, 871], "alt": [0, 1500], "status": "LC", "fact": "Around 1900, its breeding plumes were worth about twice their weight in gold. The trade nearly wiped it out, and it became the symbol of the National Audubon Society.", "links": [], "map": "img/maps/015.png", "mapSrc": "WIKIMEDIA", "seasonal": true, "fact_ca": "Cap al 1900, les seves plomes nupcials valien aproximadament el doble del seu pes en or. Aquest comerç gairebé la va fer desaparèixer, i es va convertir en el símbol de la National Audubon Society.", "family": "Ardeidae", "photo": "img/photos/015.jpg", "photoPlace": "CATALONIA"},
{"no": "016", "en": "Bearded Vulture", "short": "Bearded Vulture", "la": "Gypaetus barbatus", "cat": "Trencalòs", "local": "Quebrantahuesos", "localLang": "ES", "regions": ["EUROPE", "AFRICA", "ASIA"], "types": ["SCAVENGER", "MOUNTAIN"], "sprite": "img/sprites/016.png", "seen": [["2026-08-15", "Vall dels Voltors, La Torre de Tarmúrcia, Catalonia"]], "size": [94, 125], "weight": [5695, 5695], "alt": [1000, 5000], "status": "NT", "fact": "Bone makes up 70 to 90% of its diet. A study in the Pyrenees found it drops bones onto rocks about 4 or 5 times per session to crack them, and young birds can take years to perfect their aim.", "links": [], "map": "img/maps/016.png", "mapSrc": "IUCN", "fact_ca": "Els ossos són entre el 70 i el 90% de la seva dieta. Un estudi al Pirineu va trobar que els deixa caure sobre les roques unes 4 o 5 vegades per sessió per trencar-los, i els joves poden trigar anys a afinar la punteria.", "family": "Accipitridae", "photo": "img/photos/016.jpg", "photoPlace": "CATALONIA"},
{"no": "017", "en": "Inca Tern", "short": "Inca Tern", "la": "Larosterna inca", "cat": "Xatrac inca", "local": "Charrán inca", "localLang": "CR", "regions": ["SOUTH AMERICA"], "types": ["AQUATIC PREDATOR", "COAST"], "sprite": "img/sprites/017.png", "seen": [["2026-07-26", "Playa Pan Dulce, Golfito, Costa Rica"]], "family": "Laridae", "weight": [219, 219], "links": [], "photo": "img/photos/017.jpg", "photoPlace": "COSTA RICA", "size": [39, 42], "status": "NT", "map": "img/maps/017.png", "mapSrc": "NATURESERVE", "seasonal": true, "fact": "It lives tied to the cold Humboldt Current off Peru and Chile, feeding on anchovies. When El Niño warms the sea, the fish vanish and some terns wander north: a few have reached Costa Rica.", "fact_ca": "Viu lligat al corrent fred de Humboldt, davant del Perú i Xile, menjant peixos de la família de l'anxova. Quan El Niño escalfa el mar, el peix desapareix i alguns xatracs s'escampen cap al nord: uns quants han arribat fins a Costa Rica.", "alt": [0, 280]},
{"no": "018", "en": "Northern Jacana", "short": "Northern Jacana", "la": "Jacana spinosa", "cat": "Jacana centreamericana", "local": "Jacana centroamericana", "localLang": "CR", "regions": ["CENTRAL AMERICA"], "types": ["AQUATIC PREDATOR", "WETLAND"], "sprite": "img/sprites/018.png", "seen": [["2026-07-09", "Caño Aguas Frías, Tortuguero, Costa Rica"], ["2026-07-28", "Matapalo, Osa, Costa Rica"]], "short_ca": "Jacana", "family": "Jacanidae", "size": [17, 24], "weight": [94, 94], "status": "LC", "fact": "Its extremely long toes and claws spread its weight, so it can walk on floating leaves as if they were solid ground.", "fact_ca": "Té uns dits i unes ungles llarguíssims que li reparteixen el pes, i així pot caminar per sobre de fulles flotants com si fossin terra ferma.", "fact2": "Roles are reversed: the female is almost twice as heavy and keeps up to four males, who incubate the eggs and raise the chicks.", "fact2_ca": "Els papers estan invertits: la femella pesa gairebé el doble i té fins a quatre mascles, que coven els ous i crien els pollets.", "alt": [0, 1000], "links": [], "photo": "img/photos/018.jpg", "photoPlace": "COSTA RICA", "map": "img/maps/018.png", "mapSrc": "EBIRD"},
{"no": "019", "en": "Griffon Vulture", "short": "Griffon Vulture", "la": "Gyps fulvus", "cat": "Voltor comú", "local": "Buitre leonado", "localLang": "ES", "regions": ["EUROPE", "AFRICA", "ASIA"], "types": ["SCAVENGER", "MOUNTAIN"], "sprite": "img/sprites/019.png", "seen": [["2024-12-27", "Cingles d'Aiats, Catalonia"], ["2026-08-15", "Vall dels Voltors, La Torre de Tarmúrcia, Catalonia"]], "family": "Accipitridae", "weight": [7436, 7436], "links": [], "size": [93, 122], "wingspan": [230, 280], "status": "LC", "map": "img/maps/019.png", "mapSrc": "BIRDS OF THE WORLD", "fact": "It barely flaps: it circles inside thermals, columns of warm rising air, and then glides to the next one. Tagged griffons showed a heart rate while soaring almost as low as when resting.", "fact_ca": "Gairebé no bat les ales: fa voltes dins les tèrmiques, columnes d'aire calent que pugen, i després plana fins a la següent. Voltors amb sensors van mostrar que planant el cor els batega gairebé tan a poc a poc com en repòs.", "alt": [0, 2750], "photo": "img/photos/019.jpg", "photoPlace": "CATALONIA"},
{"no": "020", "en": "Greater Flamingo", "short": "Greater Flamingo", "la": "Phoenicopterus roseus", "cat": "Flamenc", "local": "Flamenco común", "localLang": "ES", "regions": ["EUROPE", "AFRICA", "ASIA"], "types": ["FILTER FEEDER", "WETLAND"], "sprite": "img/sprites/020.png", "seen": [["2024-08-18", "Aguait de les Dantes, Aiguamolls de l'Empordà, Catalonia"], ["2024-08-22", "Aguait de les Gantes, Aiguamolls de l'Empordà, Catalonia"], ["2024-09-10", "El Matà, Aiguamolls de l'Empordà, Catalonia"], ["2024-12-09", "Castelló d'Empúries, Catalonia"], ["2024-12-17", "Castelló d'Empúries, Catalonia"], ["2024-12-24", "Aguait de les Comes, Aiguamolls de l'Empordà, Catalonia"], ["2025-01-16", "Closa del Puig, Aiguamolls de l'Empordà, Catalonia"], ["2025-04-17", "Estany del Cortalet, Aiguamolls de l'Empordà, Catalonia"], ["2026-02-22", "Estany del Cortalet, Aiguamolls de l'Empordà, Catalonia"], ["2026-07-04", "Casa Verda, Delta de l'Ebre, Catalonia"]], "family": "Phoenicopteridae", "weight": [3032, 3032], "links": [], "size": [110, 150], "status": "LC", "map": "img/maps/020.png", "mapSrc": "BIRDS OF THE WORLD", "seasonal": true, "fact": "Flamingos are born grey. They turn pink thanks to carotenoids, the same orange-red pigments found in carrots, which they get from what they filter out of salty lagoons: brine shrimp (Artemia) and microalgae. The more carotenoids they eat, the deeper their pink.", "fact_ca": "Els flamencs neixen grisos. Es tornen rosats gràcies als carotenoides, els mateixos pigments taronja i vermells de les pastanagues, que obtenen del que filtren a les llacunes salades: l'artèmia, un petit crustaci, i les microalgues. Com més carotenoides mengen, més intens és el rosa.", "fact2": "It also wears make-up. In the breeding season it rubs its head against the preen gland, near the tail, and spreads that carotenoid-rich oil over its feathers so it looks pinker to potential mates. When courtship ends, it stops doing it and the colour fades (Amat et al. 2011).", "fact2_ca": "A més, es maquilla. En època de cria es frega el cap contra la glàndula uropigial, a prop de la cua, i s'escampa per les plomes aquell oli ric en carotenoides per semblar més rosat davant les possibles parelles. Quan s'acaba el festeig, deixa de fer-ho i el color s'apaga (Amat et al. 2011).", "alt": [0, 1400], "photo": "img/photos/020.jpg", "photoPlace": "DELTA DE L'EBRE"},
{"no": "021", "en": "Blue-footed Booby", "short": "Blue-footed Booby", "la": "Sula nebouxii", "cat": "Sula de potes blaves", "local": "Piquero patiazul", "localLang": "CR", "regions": ["CENTRAL AMERICA", "SOUTH AMERICA"], "types": ["AQUATIC PREDATOR", "COAST"], "sprite": "img/sprites/021.png", "seen": [["2026-07-26", "Playa Pan Dulce, Golfito, Costa Rica"], ["2026-07-28", "Matapalo, Osa, Costa Rica"]], "short_ca": "Sula potes blaves", "family": "Sulidae", "weight": [1520, 1520], "links": [], "photo": "img/photos/021.jpg", "photoPlace": "COSTA RICA", "size": [81, 90], "wingspan": [150, 150], "status": "LC", "map": "img/maps/021.png", "mapSrc": "BIRDS OF THE WORLD", "seasonal": true, "fact": "Its feet get their blue from pigments in fresh fish. After just two days without food, a male's feet turn duller, and females prefer the brightest feet (Velando et al. 2006).", "fact_ca": "El blau de les potes ve dels pigments del peix fresc. Amb només dos dies sense menjar, les potes d'un mascle perden color, i les femelles prefereixen les més vives (Velando et al. 2006).", "alt": [0, 100]},
{"no": "022", "en": "Goldcrest", "short": "Goldcrest", "la": "Regulus regulus", "cat": "Reietó", "local": "Reyezuelo sencillo", "localLang": "ES", "regions": ["EUROPE", "ASIA"], "types": ["INVERTIVORE", "FOREST"], "sprite": "img/sprites/022.png", "seen": [["2024-12-31", "Canal de la Tanca, Sant Llorenç del Munt i l'Obac, Catalonia"], ["2026-08-12", "Bassa d'Oles, Vielha, Catalonia"]], "family": "Regulidae", "weight": [5.5, 5.5], "links": [], "size": [8.5, 9.5], "wingspan": [13.5, 15.5], "alt": [0, 3000], "status": "LC", "map": "img/maps/022.png", "mapSrc": "BIRDS OF THE WORLD", "seasonal": true, "fact": "Together with the Firecrest, it's the smallest bird in Europe, about 5 to 6 g. On very cold nights several goldcrests may huddle together on a branch to share heat.", "fact_ca": "Amb el bruel, és l'ocell més petit d'Europa, d'uns 5 o 6 g. Les nits de molt fred, uns quants reietons es poden apilonar junts en una branca per compartir la calor.", "fact2": "Every autumn thousands cross the North Sea. They arrived on the English coast at the same time as woodcocks, so people believed they travelled on the woodcocks' backs.", "fact2_ca": "Cada tardor en creuen milers el mar del Nord. Arribaven a la costa anglesa alhora que les becades, i la gent creia que hi viatjaven a sobre.", "photo": "img/photos/022.jpg", "photoPlace": "CATALONIA"},
{"no": "023", "en": "Common Firecrest", "short": "Firecrest", "la": "Regulus ignicapilla", "cat": "Bruel", "local": "Reyezuelo listado", "localLang": "ES", "regions": ["EUROPE", "AFRICA", "ASIA"], "types": ["INVERTIVORE", "FOREST"], "sprite": "img/sprites/023.png", "seen": [["2024-09-29", "Bagà, Cadí-Moixeró, Catalonia"], ["2024-11-26", "Canaletes, Banyoles, Catalonia"]], "family": "Regulidae", "weight": [5.6, 5.6], "links": [], "size": [9, 9], "wingspan": [13, 16], "alt": [0, 2800], "status": "LC", "fact": "In Catalan it's called 'bruel', the same name as the creator of this dex.", "fact_ca": "En català es diu bruel, igual que el creador d'aquesta dex.", "fact2": "Together with the Goldcrest, it's the smallest bird in Europe: it weighs about 5 to 6 g.", "fact2_ca": "Amb el reietó, és l'ocell més petit d'Europa: pesa uns 5 o 6 g.", "map": "img/maps/023.png", "mapSrc": "MACIAG & REMISIEWICZ 2024", "seasonal": true},
{"no": "024", "en": "Eurasian Hoopoe", "short": "Hoopoe", "la": "Upupa epops", "cat": "Puput", "local": "Abubilla", "localLang": "ES", "regions": ["EUROPE", "AFRICA", "ASIA"], "types": ["INVERTIVORE", "GRASSLAND"], "sprite": "img/sprites/024.png", "seen": [["2024-08-22", "Camí Cortalet-Mas Matà, Aiguamolls de l'Empordà, Catalonia"], ["2024-12-09", "Castelló d'Empúries, Catalonia"]], "family": "Upupidae", "weight": [67, 67], "links": [], "size": [25, 32], "wingspan": [44, 48], "status": "LC", "fact": "The female and the chicks smear their eggs and feathers with a smelly oil from the preen gland. It carries bacteria that make antibiotics and protect the eggs from infection (Martín-Vivaldi et al., Granada).", "fact_ca": "La femella i els polls s'empastifen els ous i les plomes amb un oli pudent de la glàndula uropigial. Porta bacteris que fabriquen antibiòtics i protegeixen els ous d'infeccions (Martín-Vivaldi et al., Granada).", "map": "img/maps/024.png", "mapSrc": "EBIRD", "seasonal": true, "alt": [0, 4600], "photo": "img/photos/024.jpg", "photoPlace": "CATALONIA"},
{"no": "025", "en": "Common Moorhen", "short": "Moorhen", "la": "Gallinula chloropus", "cat": "Polla d'aigua", "local": "Gallineta común", "localLang": "ES", "regions": ["EUROPE", "AFRICA", "ASIA"], "types": ["OMNIVORE", "WETLAND"], "sprite": "img/sprites/025.png", "seen": [["2024-08-27", "Aguait Quim Franch, Aiguamolls de l'Empordà, Catalonia"], ["2025-04-17", "Estany del Cortalet, Aiguamolls de l'Empordà, Catalonia"]], "family": "Rallidae", "weight": [340, 340], "links": [], "size": [30, 38], "wingspan": [50, 62], "status": "LC", "fact": "Young from the first brood often stay and help feed their younger siblings from the second brood. They help more when food is plentiful (Eden 1987).", "fact_ca": "Sovint els joves de la primera cria es queden i ajuden a alimentar els germans petits de la segona. Ajuden més quan hi ha menjar de sobres (Eden 1987).", "map": "img/maps/025.png", "mapSrc": "BIRDS OF THE WORLD", "seasonal": true, "alt": [0, 3000], "photo": "img/photos/025.jpg", "photoPlace": "DELTA DE L'EBRE"},
{"no": "026", "en": "Boat-billed Heron", "short": "Boat-billed Heron", "la": "Cochlearius cochlearius", "cat": "Martinet cullerot", "local": "Garza cucharón", "localLang": "CR", "regions": ["CENTRAL AMERICA", "SOUTH AMERICA"], "types": ["AQUATIC PREDATOR", "WETLAND"], "sprite": "img/sprites/026.png", "seen": [["2026-07-09", "Caño Aguas Frías, Tortuguero, Costa Rica"]], "family": "Ardeidae", "size": [46, 54], "weight": [643, 643], "status": "LC", "fact": "It hunts at night with its huge eyes. Its wide bill works like a scoop to catch prey in muddy water.", "fact_ca": "Caça de nit amb els seus ulls enormes. El bec ample li fa de cullera per atrapar preses a l'aigua fangosa.", "fact2": "It is the only species in its genus, Cochlearius, from the Latin cochlear, 'spoon'.", "fact2_ca": "És l'única espècie del seu gènere, Cochlearius, que ve del llatí cochlear, 'cullera'. D'aquí ve també el nom de martinet cullerot.", "alt": [0, 800], "links": [], "photo": "img/photos/026.jpg", "photoPlace": "TORTUGUERO, CR", "map": "img/maps/026.png", "mapSrc": "BIRDS OF THE WORLD"},
{"no": "027", "en": "King Vulture", "short": "King Vulture", "la": "Sarcoramphus papa", "cat": "Zopilot reial", "local": "Zopilote rey", "localLang": "CR", "regions": ["CENTRAL AMERICA", "SOUTH AMERICA"], "types": ["SCAVENGER", "RAINFOREST"], "sprite": "img/sprites/027.png", "seen": [["2026-07-26", "Playa Pan Dulce, Golfito, Costa Rica"], ["2026-07-28", "Matapalo, Osa, Costa Rica"]], "family": "Cathartidae", "size": [67, 81], "weight": [3400, 3400], "status": "LC", "fact": "It can barely smell. It watches smaller vultures sniff out carcasses, then tears open the tough hide with its powerful bill.", "fact_ca": "Gairebé no té olfacte. Observa com els voltors més petits troben les carronyes amb el nas i després n'obre la pell dura amb el seu bec potent.", "alt": [0, 1500], "links": [], "photo": "img/photos/027.jpg", "photoPlace": "OSA, CR", "map": "img/maps/027.png", "mapSrc": "EBIRD"},
{"no": "028", "en": "Black Vulture", "short": "Black Vulture", "la": "Coragyps atratus", "cat": "Zopilot negre", "local": "Zopilote negro", "localLang": "CR", "regions": ["NORTH AMERICA", "CENTRAL AMERICA", "SOUTH AMERICA"], "types": ["SCAVENGER", "ADAPTABLE"], "family": "Cathartidae", "sprite": "img/sprites/028.png", "seen": [["2026-07-08", "Guápiles, Costa Rica"], ["2026-07-08", "Tortuguero, Costa Rica"], ["2026-07-14", "Sonora Jungle Retreat, Costa Rica"], ["2026-07-19", "Linda Vista del Norte, Costa Rica"], ["2026-07-28", "Matapalo, Osa, Costa Rica"]], "size": [56, 74], "weight": [1882, 1882], "status": "LC", "fact": "In Tortuguero, jaguars hunt sea turtles on the nesting beach, and black vultures finish off the carcasses (Arroyo-Arce & Salom-Pérez, 2015).", "fact_ca": "A Tortuguero, els jaguars cacen tortugues marines a la platja on ponen, i els zopilots negres s'acaben les carronyes (Arroyo-Arce i Salom-Pérez, 2015).", "fact2": "It relies on sight and follows Turkey Vultures, which can smell carcasses, then gangs up to chase them off the food.", "fact2_ca": "Es guia per la vista i segueix els zopilots capvermells, que troben les carronyes per l'olfacte. Després s'hi aplega en colla per fer-los fora del menjar.", "wingspan": [133, 167], "links": [], "photo": "img/photos/028.jpg", "photoPlace": "COSTA RICA", "map": "img/maps/028.png", "mapSrc": "BIRDS OF THE WORLD", "alt": [0, 3600]},
{"no": "029", "en": "Turkey Vulture", "short": "Turkey Vulture", "la": "Cathartes aura", "cat": "Zopilot capvermell", "local": "Zopilote cabecirrojo", "localLang": "CR", "regions": ["NORTH AMERICA", "CENTRAL AMERICA", "SOUTH AMERICA"], "types": ["SCAVENGER", "ADAPTABLE"], "family": "Cathartidae", "sprite": "img/sprites/029.png", "seen": [["2026-07-08", "Guápiles, Costa Rica"], ["2026-07-28", "Matapalo, Osa, Costa Rica"]], "weight": [1518, 1518], "links": [], "size": [62, 81], "wingspan": [150, 200], "status": "LC", "fact": "Unlike most birds, it finds carcasses by smell. In the 1930s, gas engineers in California found pipeline leaks by watching where these vultures circled.", "fact_ca": "A diferència de la majoria d'ocells, troba les carronyes per l'olfacte. Als anys 30, enginyers del gas a Califòrnia trobaven fuites als conductes mirant on feien voltes aquests zopilots.", "map": "img/maps/029.png", "mapSrc": "BIRDS OF THE WORLD", "seasonal": true, "alt": [0, 3600], "photo": "img/photos/029.jpg", "photoPlace": "COSTA RICA"},
{"no": "030", "en": "Montezuma Oropendola", "short": "Oropendola", "la": "Psarocolius montezuma", "cat": "Cacic de Moctezuma", "local": "Oropéndola de Moctezuma", "localLang": "CR", "regions": ["CENTRAL AMERICA"], "types": ["OMNIVORE", "RAINFOREST"], "sprite": "img/sprites/030.png", "seen": [["2026-07-08", "Guápiles, Costa Rica"], ["2026-07-08", "Tortuguero, Costa Rica"], ["2026-07-12", "Punta Mona, Costa Rica"], ["2026-07-14", "Sonora Jungle Retreat, Costa Rica"], ["2026-07-17", "Estación Biológica La Selva, Costa Rica"]], "family": "Icteridae", "size": [35, 48], "weight": [310, 310], "status": "LC", "fact": "Females weave about 30 hanging nests in a single tree. One dominant male courts them with a bubbling, liquid song and mates with most of them.", "fact_ca": "Les femelles teixeixen una trentena de nius penjants en un sol arbre. Un mascle dominant les festeja amb un cant líquid i borbollant i s'aparella amb la majoria.", "fact2": "While singing, the male bows deeply forward on his perch.", "fact2_ca": "Mentre canta, el mascle fa una reverència profunda endavant sobre la branca.", "alt": [0, 1500], "links": [], "photo": "img/photos/030.jpg", "photoPlace": "COSTA RICA", "map": "img/maps/030.png", "mapSrc": "EBIRD"},
{"no": "031", "en": "Rufous Motmot", "short": "Rufous Motmot", "la": "Baryphthengus martii", "cat": "Motmot rogenc", "local": "Momoto canelo", "localLang": "CR", "regions": ["CENTRAL AMERICA", "SOUTH AMERICA"], "types": ["OMNIVORE", "RAINFOREST"], "family": "Momotidae", "sprite": "img/sprites/031.png", "seen": [["2026-07-14", "Aranwa Sarapiquí Rainforest Lodge, Costa Rica"], ["2026-07-15", "Tirimbina Rainforest Center, Costa Rica"]], "weight": [165, 165], "size": [42, 47], "alt": [0, 1250], "status": "LC", "fact": "It swings its long tail from side to side like a pendulum to tell predators: I've seen you, don't bother chasing me.", "fact_ca": "Balanceja la cua llarga d'un costat a l'altre com un pèndol per avisar els depredadors: t'he vist, no cal que m'empaitis.", "fact2": "The rackets at the tip of its tail aren't trimmed by the bird, as people once believed: the barbs on that stretch are weakly attached and simply fall off.", "fact2_ca": "Les raquetes de la punta de la cua no se les retalla l'ocell, com es creia: les barbes d'aquell tros estan poc enganxades i cauen soles.", "photo": "img/photos/031.jpg", "photoPlace": "SARAPIQUI, CR", "map": "img/maps/031.png", "mapSrc": "EBIRD", "links": []},
{"no": "032", "en": "Buff-rumped Warbler", "short": "Buff-rumped Warbler", "la": "Myiothlypis fulvicauda", "cat": "Bosquerola de carpó clar", "local": "Reinita guardaribera", "localLang": "CR", "regions": ["CENTRAL AMERICA", "SOUTH AMERICA"], "types": ["INVERTIVORE", "RAINFOREST"], "family": "Parulidae", "seen": [["2026-07-18", "Hotel Linda Vista, Costa Rica"]], "sprite": "img/sprites/032.png", "links": [], "weight": [15, 15], "size": [13, 13.5], "alt": [0, 1500], "status": "LC", "fact": "It never strays far from water. Each pair defends the same stretch of stream all year, hopping along the banks and catching insects on the ground.", "fact_ca": "No s'allunya mai de l'aigua. Cada parella defensa el mateix tram de rierol tot l'any, saltant per les vores i caçant insectes a terra.", "fact2": "It constantly pumps its broad tail. In related warblers, sudden tail flashes have been shown to startle insects into fleeing so they are easier to catch, and it probably works the same way here.", "fact2_ca": "Mou constantment la cua ampla. En ocells parents s'ha vist que obrir la cua de cop espanta els insectes i els fa fugir, i així és més fàcil caçar-los. Probablement aquí funciona igual.", "photo": "img/photos/032.jpg", "photoPlace": "COSTA RICA", "map": "img/maps/032.png", "mapSrc": "EBIRD"},
{"no": "033", "en": "Scarlet-rumped Tanager", "short": "Scarlet-rumped Tanager", "la": "Ramphocelus passerinii", "cat": "Tàngara de carpó vermell", "local": "Tangara lomiescarlata", "localLang": "CR", "regions": ["CENTRAL AMERICA"], "types": ["OMNIVORE", "ADAPTABLE"], "family": "Thraupidae", "seen": [["2026-07-11", "Sonora Jungle Retreat, Costa Rica"]], "sprite": "img/sprites/033.png", "links": [], "weight": [32, 32], "size": [15, 17], "alt": [0, 1700], "status": "LC", "fact": "Costa Rica's Caribbean and Pacific populations were long treated as two species, Passerini's and Cherrie's Tanager. Males look almost identical; the females give them away: Pacific females have a bright orange breast.", "fact_ca": "Les poblacions del Carib i del Pacífic de Costa Rica s'han considerat molt temps dues espècies, la tàngara de Passerini i la de Cherrie. Els mascles són gairebé iguals; les delaten les femelles: les del Pacífic tenen el pit taronja viu.", "map": "img/maps/033.png", "mapSrc": "WIKIMEDIA", "photo": "img/photos/033.jpg", "photoPlace": "COSTA RICA"},
{"no": "034", "en": "Common Shelduck", "short": "Shelduck", "la": "Tadorna tadorna", "cat": "Ànec blanc", "local": "Tarro blanco", "localLang": "ES", "regions": ["EUROPE", "AFRICA", "ASIA"], "types": ["AQUATIC PREDATOR", "WETLAND"], "family": "Anatidae", "seen": [["2024-08-10", "Aguait de les Dantes, Aiguamolls de l'Empordà, Catalonia"]], "sprite": "img/sprites/034.png", "links": [], "weight": [1147, 1147], "size": [55, 65], "wingspan": [100, 120], "status": "LC", "map": "img/maps/034.png", "mapSrc": "WIKIMEDIA", "seasonal": true, "fact": "It often nests in old rabbit burrows. After breeding, most adults from northwest Europe fly to the Wadden Sea to moult, leaving their chicks in crèches looked after by a few adults.", "fact_ca": "Sovint fa el niu en caus vells de conill. Després de criar, la majoria d'adults del nord-oest d'Europa marxen al mar de Wadden a mudar la ploma i deixen els polls en guarderies vigilades per uns quants adults.", "alt": [0, 2400], "photo": "img/photos/034.jpg", "photoPlace": "CATALONIA"},
{"no": "035", "en": "Ruddy Shelduck", "short": "Ruddy Shelduck", "la": "Tadorna ferruginea", "cat": "Ànec canyella", "local": "Tarro canelo", "localLang": "ES", "regions": ["EUROPE", "AFRICA", "ASIA"], "types": ["HERBIVORE", "WETLAND"], "family": "Anatidae", "seen": [["2026-03-12", "Estany de Puigcerdà, Catalonia"]], "sprite": "img/sprites/035.png", "links": [], "weight": [1235, 1235], "size": [58, 70], "wingspan": [110, 135], "alt": [0, 5000], "status": "LC", "map": "img/maps/035.png", "mapSrc": "BIRDS OF THE WORLD", "seasonal": true, "fact": "Tibetan and Mongolian Buddhists consider it sacred, so it's rarely hunted there. It nests in holes in cliffs and banks, sometimes far from water.", "fact_ca": "Els budistes del Tibet i de Mongòlia el consideren sagrat, i per això allà gairebé no el cacen. Fa el niu en forats de cingles i talussos, de vegades lluny de l'aigua.", "photo": "img/photos/035.jpg", "photoPlace": "CATALONIA"},
{"no": "036", "en": "Mallard", "short": "Mallard", "la": "Anas platyrhynchos", "cat": "Ànec collverd", "local": "Ánade azulón", "localLang": "ES", "regions": ["EUROPE", "AFRICA", "ASIA", "NORTH AMERICA"], "types": ["HERBIVORE", "WETLAND"], "weight": [843, 843], "family": "Anatidae", "seen": [["2024-08-10", "Aguait de les Dantes, Aiguamolls de l'Empordà, Catalonia"]], "sprite": "img/sprites/036.png", "links": [], "size": [50, 65], "wingspan": [81, 98], "status": "LC", "map": "img/maps/036.png", "mapSrc": "BIRDS OF THE WORLD", "seasonal": true, "fact": "It's the ancestor of almost all domestic ducks. Only the Muscovy duck comes from a different wild species.", "fact_ca": "És l'avantpassat de gairebé tots els ànecs domèstics. Només l'ànec mut ve d'una altra espècie salvatge.", "fact2": "It can sleep with one eye open and half its brain awake. Ducks at the end of a sleeping row keep their outer eye open to watch for predators (Rattenborg et al. 1999).", "fact2_ca": "Pot dormir amb un ull obert i la meitat del cervell desperta. Els ànecs dels extrems d'una filera que dorm mantenen obert l'ull de fora per vigilar els depredadors (Rattenborg et al. 1999).", "alt": [0, 3700], "photo": "img/photos/036.jpg", "photoPlace": "CATALONIA"},
{"no": "037", "en": "Eurasian Teal", "short": "Teal", "la": "Anas crecca", "cat": "Xarxet comú", "local": "Cerceta común", "localLang": "ES", "regions": ["EUROPE", "AFRICA", "ASIA"], "types": ["HERBIVORE", "WETLAND"], "weight": [342, 342], "family": "Anatidae", "seen": [["2024-12-09", "Castelló d'Empúries, Catalonia"]], "sprite": "img/sprites/037.png", "links": [], "size": [34, 43], "wingspan": [53, 59], "status": "LC", "fact": "The colour teal is named after this duck, from the green patch around its eye.", "fact_ca": "El color teal (un blau verdós) rep el nom d'aquest ànec, per la taca verda que té al voltant de l'ull.", "fact2": "It doesn't always migrate along the same route: ringing in the Camargue showed that about 1 in 5 teal switch flyways (Guillemain et al. 2006).", "fact2_ca": "No sempre migra pel mateix camí: els anellaments a la Camarga van mostrar que aproximadament 1 de cada 5 xarxets canvia de ruta migratòria (Guillemain et al. 2006).", "map": "img/maps/037.png", "mapSrc": "WIKIMEDIA", "seasonal": true, "alt": [0, 3350], "photo": "img/photos/037.jpg", "photoPlace": "CATALONIA"},
{"no": "038", "en": "Brown Pelican", "short": "Brown Pelican", "la": "Pelecanus occidentalis", "cat": "Pelicà bru", "local": "Pelícano pardo", "localLang": "CR", "regions": ["NORTH AMERICA", "CENTRAL AMERICA", "SOUTH AMERICA"], "types": ["AQUATIC PREDATOR", "COAST"], "weight": [3428, 3428], "family": "Pelecanidae", "seen": [["2026-07-22", "Playa Agujas, Costa Rica"], ["2026-07-26", "Playa Pan Dulce, Golfito, Costa Rica"], ["2026-07-28", "Matapalo, Osa, Costa Rica"]], "sprite": "img/sprites/038.png", "links": [], "photo": "img/photos/038.jpg", "photoPlace": "COSTA RICA", "size": [100, 152], "wingspan": [203, 228], "status": "LC", "fact": "Unlike most pelicans, which fish while swimming, it plunges headfirst into the sea from the air.", "fact_ca": "A diferència de la majoria de pelicans, que pesquen nedant, es llança de cap al mar des de l'aire.", "fact2": "The pesticide DDT made its eggshells so thin that parents crushed them while incubating. By 1963 it had vanished from Louisiana, the 'Pelican State'. After the US ban in 1972 it recovered.", "fact2_ca": "El pesticida DDT li feia la closca dels ous tan prima que els pares la trencaven en covar. El 1963 havia desaparegut de Louisiana, l'estat del pelicà. Després de la prohibició als EUA el 1972 es va recuperar.", "map": "img/maps/038.png", "mapSrc": "BIRDS OF THE WORLD", "seasonal": true, "alt": [0, 100]},
{"no": "039", "en": "Anhinga", "short": "Anhinga", "la": "Anhinga anhinga", "cat": "Anhinga americana", "local": "Pato aguja", "localLang": "CR", "regions": ["NORTH AMERICA", "CENTRAL AMERICA", "SOUTH AMERICA"], "types": ["AQUATIC PREDATOR", "WETLAND"], "weight": [1235, 1235], "family": "Anhingidae", "seen": [["2026-07-09", "Caño Aguas Frías, Tortuguero, Costa Rica"]], "sprite": "img/sprites/039.png", "links": [], "photo": "img/photos/039.jpg", "photoPlace": "TORTUGUERO, CR", "size": [75, 95], "wingspan": [114, 114], "status": "LC", "fact": "Its feathers aren't waterproof: they soak through to the body, so it floats less and swims with only its long neck out, like a snake. That's why it's called the snakebird.", "fact_ca": "Les plomes no són impermeables: es mullen fins al cos, així sura menys i neda amb només el coll llarg fora de l'aigua, com una serp. Per això li diuen ocell serp.", "fact2": "Afterwards it has to perch with its wings spread to the sun. Besides drying, this warms it up: it produces little body heat and loses a lot when wet.", "fact2_ca": "Després s'ha de posar amb les ales obertes al sol. A més d'assecar-se, s'escalfa: produeix poca calor corporal i en perd molta quan és mullat.", "map": "img/maps/039.png", "mapSrc": "BIRDS OF THE WORLD", "seasonal": true, "alt": [0, 1000]},
{"no": "040", "en": "Little Grebe", "short": "Little Grebe", "la": "Tachybaptus ruficollis", "cat": "Cabusset", "local": "Zampullín común", "localLang": "ES", "regions": ["EUROPE", "AFRICA", "ASIA"], "types": ["AQUATIC PREDATOR", "WETLAND"], "pending": true, "family": "Podicipedidae", "weight": [169, 169], "size": [25, 29], "wingspan": [40, 45], "alt": [0, 4000], "status": "LC", "links": [], "seen": [["2024-08-14", "Aguait Quim Franch, Catalonia"], ["2024-08-22", "Aguait Quim Franch, Aiguamolls de l'Empordà, Catalonia"], ["2024-08-27", "Aguait Quim Franch, Aiguamolls de l'Empordà, Catalonia"], ["2024-12-09", "Castelló d'Empúries, Catalonia"], ["2024-12-17", "Castelló d'Empúries, Catalonia"], ["2024-12-24", "aguait de les comes(?), Catalonia"], ["2025-01-16", "Closa del Puig, Aiguamolls de l'Empordà, Catalonia"], ["2025-04-17", "Estany del Cortalet, Aiguamolls de l'Empordà, Catalonia"], ["2026-02-22", "Estany del Cortalet, Aiguamolls de l'Empordà, Catalonia"]], "fact": "Like all grebes, it swallows its own feathers. They form a ball in its stomach that seems to slow digestion and protect the gut from sharp fish bones.", "fact_ca": "Com tots els cabussons, s'empassa les seves pròpies plomes. A l'estómac formen una bola que sembla que alenteix la digestió i protegeix l'intestí de les espines.", "sprite": "img/sprites/040.png", "photo": "img/photos/040.jpg", "photoPlace": "CATALONIA"},
{"no": "041", "en": "Eurasian Spoonbill", "short": "Eurasian Spoonbill", "la": "Platalea leucorodia", "cat": "Becplaner", "local": "Espátula común", "localLang": "ES", "regions": ["EUROPE", "AFRICA", "ASIA"], "types": ["AQUATIC PREDATOR", "WETLAND"], "pending": true, "family": "Threskiornithidae", "weight": [1868, 1868], "size": [70, 95], "wingspan": [115, 135], "alt": [0, 915], "status": "LC", "links": [], "seen": [["2024-08-22", "Aguait Quim Franch, Aiguamolls de l'Empordà, Catalonia"], ["2024-08-22", "Aguait de les Gantes, Aiguamolls de l'Empordà, Catalonia"], ["2026-02-22", "Estany del Cortalet, Aiguamolls de l'Empordà, Catalonia"]], "fact": "It hunts by touch: it sweeps its half-open bill from side to side through the water and snaps it shut the instant it feels prey.", "fact_ca": "Caça al tacte: escombra l'aigua amb el bec mig obert d'un costat a l'altre i el tanca de cop quan toca una presa.", "fact2": "In the Netherlands fewer than 150 pairs were left in 1968. By 2015 there were almost 3,000, thanks to wetland protection and the ban on DDT.", "fact2_ca": "Als Països Baixos en quedaven menys de 150 parelles el 1968. El 2015 ja n'hi havia gairebé 3.000, gràcies a la protecció dels aiguamolls i la prohibició del DDT.", "sprite": "img/sprites/041.png"},
{"no": "042", "en": "White-throated Dipper", "short": "Dipper", "la": "Cinclus cinclus", "cat": "Merla d'aigua", "local": "Mirlo acuático", "localLang": "ES", "regions": ["EUROPE", "AFRICA", "ASIA"], "types": ["AQUATIC PREDATOR", "MOUNTAIN"], "pending": true, "family": "Cinclidae", "weight": [61.5, 61.5], "size": [17, 20], "wingspan": [25, 30], "alt": [0, 4800], "status": "LC", "links": [], "seen": [["2026-08-12", "Arties, Val d'Aran, Catalonia"]], "fact": "It's the only kind of songbird that dives and swims underwater. It walks along the bottom of fast streams, against the current, to catch insect larvae.", "fact_ca": "És l'únic tipus d'ocell cantor que es capbussa i neda sota l'aigua. Camina pel fons dels rierols, contra corrent, per caçar larves d'insectes.", "fact2": "Over the roar of the river, it flashes its white eyelids instead of singing louder when other dippers are nearby (de Framond et al. 2025).", "fact2_ca": "Quan el riu fa molt soroll i té altres merles a prop, en lloc de cantar més fort parpelleja amb les parpelles blanques (de Framond et al. 2025).", "sprite": "img/sprites/042.png"},
{"no": "043", "en": "Eurasian Nuthatch", "short": "Nuthatch", "la": "Sitta europaea", "cat": "Pica-soques blau", "local": "Trepador azul", "localLang": "ES", "regions": ["EUROPE", "AFRICA", "ASIA"], "types": ["INVERTIVORE", "FOREST"], "pending": true, "family": "Sittidae", "weight": [20.4, 20.4], "size": [12, 14.5], "wingspan": [22.5, 27], "alt": [0, 3300], "status": "LC", "links": [], "seen": [["2024-12-26", "Pantà de Sau, Catalonia"]], "fact": "Unlike woodpeckers and treecreepers, it can climb down a tree trunk head-first. It doesn't lean on its tail: its strong feet do all the work.", "fact_ca": "A diferència dels picots i els raspinells, pot baixar pels troncs de cap per avall. No es recolza en la cua: ho fa tot amb les potes, molt fortes.", "fact2": "It plasters the entrance of its nest hole with mud until it's just big enough for itself, keeping out bigger birds that would steal the nest.", "fact2_ca": "Tapa l'entrada del niu amb fang fins que només hi cap ell, i així evita que ocells més grans li prenguin el forat.", "sprite": "img/sprites/043.png"},
{"no": "044", "en": "Little Egret", "short": "Little Egret", "la": "Egretta garzetta", "cat": "Martinet blanc", "local": "Garceta común", "localLang": "ES", "regions": ["EUROPE", "AFRICA", "ASIA", "OCEANIA"], "types": ["AQUATIC PREDATOR", "WETLAND"], "pending": true, "family": "Ardeidae", "weight": [312, 312], "size": [55, 65], "wingspan": [88, 106], "alt": [0, 2270], "status": "LC", "links": [], "seen": [["2024-08-12", "Aguait de les Dantes, Aiguamolls de l'Empordà, Catalonia"], ["2026-02-22", "Estany del Cortalet, Aiguamolls de l'Empordà, Catalonia"], ["2026-07-04", "Casa Verda, Delta de l'Ebre, Catalonia"]], "fact": "Black legs, bright yellow feet. It shuffles those feet in the mud and shallow water to flush out hidden fish and shrimps, then spears them.", "fact_ca": "Potes negres i peus groc intens. Remena el fang i l'aigua poc fonda amb els peus per fer sortir peixos i gambetes amagats, i llavors els arpona.", "fact2": "Its breeding plumes were so prized for 19th-century hats that it was nearly wiped out in Europe. Protests against the plume trade led to the founding of the RSPB in 1889.", "fact2_ca": "Les seves plomes de cria eren tan preuades per als barrets del segle XIX que gairebé va desaparèixer d'Europa. Les protestes contra aquest comerç van fer néixer la RSPB el 1889.", "sprite": "img/sprites/044.png"}
];
